14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "bulkSignupWarning",
29	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
30	    @Mapping(target = "possibleDuplicate",
31	        expression = "java(Boolean.TRUE.equals(owner.getPossibleDuplicate()))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "telephoneDisplay",
35	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones.toDisplay(owner.getTelephone()))")
36	    @Mapping(target = "identityKey",
37	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's age band from the {@code birthDate} measured against the
42	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
43	     * 64 inclusive and {@code SENIOR} at 65 or over. Null when no birth date is present.
44	     */
45	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
46	        java.time.LocalDate birthDate = owner.getBirthDate();
47	        if (birthDate == null) {
48	            return null;
49	        }
50	        java.time.LocalDate reference = owner.getRegistrationDate() != null
51	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
52	        int years = java.time.Period.between(birthDate, reference).getYears();
